  const renderExperience=p=>p.experience.map(x=>`<article class="cv-job"><div class="cv-period">${x.period}</div><div><h4>${x.company}</h4><b>${x.position}</b><p>${x.text}</p><small>${x.stack}</small></div></article>`).join('');

