        <aside class="profile-zone profile-command-center"><div class="profile-vacancy-action"><button class="take-vacancy-button" data-action="take-vacancy" aria-expanded="${profilePopover==='vacancy'}"><span>${icon('plus')}</span><b>Взять на вакансию</b></button>${vacancyPicker}</div><div class="profile-action-grid">${profileAction('Доп. информация','candidate-more','info')}${profileAction('Редактировать','edit-candidate','edit')}${profileAction('Задача','new-task','check')}${profileAction('Встреча','new-meeting','calendar-20')}</div><section class="profile-ai-summary"><header><span>AI</span><div><b>ИИ-саммари</b><strong>${c.score}${c.score==='Ошибка'?'':' / 10'}</strong></div></header><p>${p.summary}</p><div class="criteria-row"><span class="good">✓ Профильный опыт</span><span class="good">✓ Ключевой стек</span><span class="warn">△ Проверить мотивацию</span></div><button data-action="override-ai">Открыть полную оценку →</button></section></aside>
